from sentence_transformers import SentenceTransformer
import numpy as np
import pandas as pd

model = SentenceTransformer("sentence-transformers/paraphrase-multilingual-mpnet-base-v2")

sentences = [
    "[Waspada] Waktu pengukuran jam 12:00 WIB termasuk Siang Hari. Suhu 29.0 °C berada di atas rentang optimal (18–26 °C) dan termasuk waspada karena dapat menyebabkan stres panas pada bawang putih tunggal. Kelembapan udara 58.0 % sedikit di bawah rentang optimal (60–80 %), namun masih dalam batas toleransi. Intensitas cahaya 1368.5 lux pada siang hari tergolong normal (cerah wajar) dalam rentang 400-1500 lux. Kelembapan tanah 59.0 % berada dalam rentang optimal (50–70 %). Secara keseluruhan, suhu yang tinggi menjadi faktor utama yang perlu diwaspadai. Rekomendasi:Tingkatkan sirkulasi udara atau aktifkan sistem pendingin (kipas/misting) untuk menurunkan suhu udara. Pantau kelembapan udara dan lakukan penyemprotan kabut jika turun di bawah 55%. Periksa kondisi tanaman untuk tanda-tanda stres panas dan siram tanah jika diperlukan untuk menjaga kelembapan tanah tetap optimal.",
    "[Waspada] Waktu pengukuran siang hari (12:00 WIB). Suhu 29.0°C di atas rentang optimal (18-26°C), perlu waspada. Kelembapan udara 58% di bawah optimal (60-80%), menunjukkan kondisi kering. Intensitas cahaya 1368.5 lux dalam rentang normal siang hari (400-1500 lux), sehingga tidak bermasalah. Kelembapan tanah 59% berada dalam rentang optimal (50-70%). Kondisi utama yang perlu diwaspadai adalah suhu tinggi dan kelembapan udara rendah. Rekomendasi: Aktifkan sistem pendingin atau ventilasi untuk menurunkan suhu udara. Tingkatkan kelembapan udara dengan fogging atau penyemprotan air. Pantau kelembapan tanah dan pastikan penyiraman terjadwal jika diperlukan.",
    "[Waspada] Waktu pengukuran jam 12:00 WIB termasuk Siang Hari. Suhu udara 29.0 °C berada di atas rentang optimal (18–26 °C) dan termasuk berbahaya karena dapat menyebabkan stres panas pada tanaman bawang putih tunggal. Kelembapan udara 58.0 % sedikit di bawah rentang optimal (60–80 %), namun masih dalam batas toleransi. Intensitas cahaya 1368.5 lux pada siang hari tergolong normal dan wajar untuk kondisi cerah. Kelembapan tanah 59.0 % berada dalam rentang optimal (50–70 %). Secara keseluruhan, suhu yang tinggi menjadi faktor utama yang perlu diwaspadai. Rekomendasi: Segera aktifkan sistem pendingin atau naungan untuk menurunkan suhu udara di dalam greenhouse. Tingkatkan sirkulasi udara dengan kipas atau ventilasi untuk mengurangi stres panas pada tanaman. Pantau kelembapan udara dan pertimbangkan penyemprotan kabut (fogging) jika kelembapan turun di bawah 50%.",
    "[Waspada] Waktu pengukuran jam 12:00 WIB termasuk Siang Hari. Suhu 29.0 °C berada di atas rentang optimal (18–26 °C) dan termasuk waspada karena dapat menyebabkan stres panas pada bawang putih tunggal. Kelembapan udara 58.0 % sedikit di bawah rentang optimal (60–80 %), namun masih dalam batas toleransi. Intensitas cahaya 1368.5 lux pada siang hari tergolong normal (cerah wajar). Kelembapan tanah 59.0 % berada dalam rentang optimal (50–70 %). Secara keseluruhan, suhu yang tinggi menjadi faktor utama yang perlu diwaspadai. Rekomendasi: Segera aktifkan sistem pendingin atau naungan untuk menurunkan suhu udara di dalam greenhouse. Tingkatkan kelembapan udara dengan mengaktifkan misting atau penyemprotan air halus secara berkala. Pantau suhu dan kelembapan secara kontinu, terutama pada jam-jam siang hari, untuk mencegah dampak negatif pada pertumbuhan bawang putih tunggal.",
    "[Waspada] Waktu pengukuran jam 12:00 WIB termasuk Siang Hari. Suhu 29.0 °C berada di atas rentang optimal (18–26 °C) dan termasuk berbahaya karena dapat menyebabkan stres panas pada bawang putih tunggal. Kelembapan udara 58.0 % sedikit di bawah rentang optimal (60–80 %), namun masih dalam batas toleransi. Intensitas cahaya 1368.5 lux pada siang hari tergolong normal (cerah wajar). Kelembapan tanah 59.0 % berada dalam rentang optimal (50–70 %). Secara keseluruhan, suhu yang tinggi menjadi faktor risiko utama yang perlu diwaspadai. Rekomendasi: Segera aktifkan sistem pendingin atau naungan untuk menurunkan suhu udara di dalam greenhouse. Tingkatkan kelembapan udara dengan mengaktifkan misting atau penyemprotan air secara berkala. Pantau suhu secara kontinu dan hindari penyiraman berlebihan pada tanah karena kelembapan tanah sudah optimal."]

embeddings = model.encode(sentences)
similarities = model.similarity(embeddings, embeddings)

labels = ['A', 'B', 'C', 'D', 'E']
df = pd.DataFrame(similarities.numpy(), index=labels, columns=labels)
print("Matriks Similarity:")
print(df.round(4))

sim_matrix = similarities.numpy()
upper_tri = sim_matrix[np.triu_indices(len(sentences), k=1)]

mean_similarity = upper_tri.mean()
std_similarity = upper_tri.std()

print(f"Mean similarity: {upper_tri.mean():.4f}")

print(f"SD: {upper_tri.std():.4f}")

print(f"Hasil akhir: {mean_similarity:.4f} ± {std_similarity:.4f}")